/** A smooth closed curve through the points (Catmull-Rom as cubic Béziers). */
function smoothPath(points: Point[]) {
  const n = points.length;
  const at = (i: number) => points[(i + n) % n];
  let d = `M${points[0][0]},${points[0][1]}`;
  for (let i = 0; i < n; i++) {
    const [p0, p1, p2, p3] = [at(i - 1), at(i), at(i + 1), at(i + 2)];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += ` C${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${p2[0]},${p2[1]}`;
  }
  return `${d} Z`;
}

/** SVG paths of the outline for each pose, by sex. The back view has the same outline as the front. */
export const OUTLINES: Record<Sex, Record<PhotoPose, string[]>> = {
  male: {
    front: [MALE_FRONT],
    back: [MALE_FRONT],
    side: [smoothPath(MALE_SIDE), smoothPath(MALE_ARM)],
  },
  female: {
    front: [FEMALE_FRONT],
    back: [FEMALE_FRONT],
    side: [smoothPath(FEMALE_SIDE), smoothPath(FEMALE_ARM)],
  },
};
